def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Get the manifest for the application
    manifest = app.spec.manifest

    # Iterate over each resource in the manifest
    for resource in manifest:
        # Check if a custom observer schema has been specified for this resource
        if resource.metadata.annotations.get("krake.io/observer-schema"):
            # If a custom observer schema has been specified, skip this resource
            continue

        # Generate a default observer schema for this resource
        observer_schema = {
            "type": "object",
            "properties": {
                "status": {
                    "type": "object",
                    "properties": {
                        "observedGeneration": {
                            "type": "integer"
                        },
                        "conditions": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "type": {
                                        "type": "string"
                                    },
                                    "status": {
                                        "type": "string"
                                    },
                                    "lastTransitionTime": {
                                        "type": "string",
                                        "format": "date-time"
                                    },
                                    "reason": {
                                        "type": "string"
                                    },
                                    "message": {
                                        "type": "string"
                                    }
                                },
                                "required": [
                                    "type",
                                    "status",
                                    "lastTransitionTime",
                                    "reason",
                                    "message"
                                ]
                            }
                        }
                    }
                }
            }
        }

