def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = sys.platform
    if platform == 'win32':
        return _split_windows(s)
    else:
        return _split_posix(s)

def _split_windows(s):
    # Use a regular expression to split the string into tokens,
    # treating double quotes as a special case.
    tokens = re.split(r'(\"[^\"]*\")', s)
    for i, token in enumerate(tokens):
        if token.startswith('"') and token.endswith('"'):
            # Remove the double quotes from the token.
            tokens[i] = token[1:-1]
    return tokens

def _split_posix(s):
    # Use a regular expression to split the string into tokens,
    # treating single quotes as a special case.
    tokens = re.split(r"('[^']*')", s)
    for i, token in enumerate(tokens):
        if token.startswith("'") and token.endswith("'"):
            # Remove the single quotes from the token.
            tokens[i] = token[1:-1]
    return tokens
