def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        return {
            "subject": data["subject"],
            "aliases": data["aliases"],
            "links": data["links"],
            "properties": data["properties"]
        }
    except json.JSONDecodeError:
        pass

    try:
        xrd = XRD.parse(document)
        return {
            "subject": xrd.subject,
            "aliases": xrd.aliases,
            "links": xrd.links,
            "properties": xrd.properties
        }
    except XRD.ParseError:
        raise ValueError("Invalid Diaspora webfinger document")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        response = requests.get(f"https://{handle}/.well-known/webfinger")
        if response.status_code == 200:
            return response.json()
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from xml.etree import ElementTree

    response = requests.get(f"https://{handle}/.well-known/webfinger")
    if response.status_code == 200:
        xml_data = response.content
        root = ElementTree.fromstring(xml_data)
        links = root.findall(".//{http://www.w3.org/2005/Atom}link")
        for link in links:
            if link.attrib["rel"] == "http://schemas.google.com/g/2010#updates-from":
                return {"updates_from": link.attrib["href"]}
    return {}

